INSERT IGNORE INTO `base_config` (`id`, `site`, `name`, `type`, `key`, `value`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3003, 3, '隐私协议', 3, 'privacyProtocol', '<h2>隐私政策</h2><p>感谢您使用本应用。我们重视并保护您的个人信息，仅在提供账号登录、应用功能和客户服务所必需的范围内处理相关信息。</p><h3>一、信息使用</h3><p>我们会按照法律法规和本协议约定使用您的信息，不会将其用于无关目的。</p><h3>二、您的权利</h3><p>您可以依法查询、更正、删除个人信息，或通过应用内公布的渠道联系我们。</p>', 1, 1, 1, '2026-07-16 14:02:47', '2026-07-17 18:55:12', 0);
INSERT IGNORE INTO `base_config` (`id`, `site`, `name`, `type`, `key`, `value`, `status`, `created_by`, `updated_by`, `created_at`, `updated_at`, `deleted_at`) VALUES (3004, 3, '服务条款', 3, 'serviceProtocol', '<h2>服务条款</h2><p>欢迎使用本应用。使用本应用前，请您阅读并理解本协议。您开始使用应用服务，即表示同意遵守本协议及相关规则。</p><h3>一、服务使用</h3><p>请您依法、合规并按照页面提示使用各项功能，不得利用本应用从事违法或损害他人权益的活动。</p><h3>二、协议变更</h3><p>我们会根据业务和法律法规变化更新本协议，并在应用内向您展示更新后的内容。</p>', 1, 1, 1, '2026-07-13 15:25:41', '2026-07-26 07:45:19', 0);
